def submit_dispatch(cmd):
    if seen(cmd.idempotency_key):
        return prior_result(cmd.idempotency_key)   # exactly-once
    target = clamp(cmd.setpoint, envelope(cmd.unit)) # never exceed certified limit
    ramp   = rate_limit_ramp(target, current_state())# respect slew limits
    ticket = L1.stage(cmd.unit, ramp)                # twin/failsafe authoritative
    record(cmd.idempotency_key, ticket)
    return {'accepted': True, 'clamped': target != cmd.setpoint,
            'ticket': ticket, 'eta_s': ramp.duration}

# accept a neutron-service booking only if breeding stays on target
def book(service_req):
    fluence = service_req.fluence            # n/cm^2 over window
    diverted = neutrons_for(fluence)
    tbr_after = projected_tbr(diverted)      # twin neutronics
    if tbr_after >= tbr_target():
        return schedule(service_req)
    else:
        return defer(service_req, reason='TBR floor')

# RUL as time until a health index crosses a limit
# health index h(t) from twin (strain, resistance, thermal margin ...)
def rul(component, now):
    traj = degradation_model(component).forecast(h_history(component))
    for t in future_times(now):
        if traj.mean(t) - k*traj.std(t) <= h_limit(component):
            return t - now                 # conservative RUL (lower band)
    return horizon                          # beyond horizon: no action
# model is shared across fleet units of the same component type

# trigger procurement when predicted-need minus lead-time is near
for comp in fleet_components():
    need_date = now + rul(comp, now)          # from predictive maintenance
    order_by  = need_date - lead_time(comp.type) - safety_margin
    if now >= order_by and not staged(comp.type):
        procure(comp.type)                    # start long-lead manufacture
    if staged(comp.type) and expiring(spare(comp.type)):
        requalify(spare(comp.type))           # shelf-life / re-cert

# validate a remote-handling motion plan against the twin
def safe_plan(plan, comp):
    twin_scene = twin_geometry(comp.location)      # live geometry
    dose_field = twin_dose_map(comp.location)       # residual activation
    if collides(plan, twin_scene): return reject('collision')
    if cumulative_dose(plan, dose_field) > tool_limit:
        return reject('dose to tooling/electronics')
    return approve(plan)                            # then execute teleop

# federated-style propagation with per-unit validation gate
def propagate(update, source_unit):
    for u in fleet_peers(source_unit):
        if not compatible(update, generation(u), config(u)):
            continue
        score = validate(update, twin(u), holdout_history(u))
        if score >= accept_threshold and safety_review(update, u):
            stage(update, u)          # into shadow, then L3 after soak
# raw telemetry stays local; only validated model deltas move
